<?php

/**
 * AnaUserLoginTable
 * 
 * This class has been auto-generated by the Doctrine ORM Framework
 */
class AnaUserLoginTable extends Doctrine_Table
{
    /**
     * Returns an instance of this class.
     *
     * @return object AnaUserLoginTable
     */
    public static function getInstance()
    {
        return Doctrine_Core::getTable('AnaUserLogin');
    }
		
		public static function doLogin($username = "", $password = ""){
		$query = Doctrine_Core::getTable('AnaUsers')
		 ->createQuery('u')
		 ->where('u.username=?',$username)
		 ->andWhere('u.password=?',md5($password))
		 ->andWhere('u.status=?','1');
		 
//		 echo $query->getSqlQuery(); exit;
		 
		return $query->execute();
	 }
}